mapper.select:
select v.id, v.user_id, v.target_type, v.target_id, v.view_time, u.nickname, u.avatar_url, case v.target_type when 'city' then c.name when 'attraction' then a.name when 'guide' then g.title else null end as target_title, case v.target_type when 'city' then c.cover_image when 'attraction' then a.cover_image when 'guide' then g.cover_image else null end as target_cover_image from voya_ai_view_log v left join voya_ai_user u on v.user_id = u.id left join voya_ai_city c on v.target_type = 'city' and v.target_id = c.id and c.del_flag = '0' left join voya_ai_attraction a on v.target_type = 'attraction' and v.target_id = a.id and a.del_flag = '0' left join voya_ai_guide g on v.target_type = 'guide' and v.target_id = g.id and g.del_flag = '0'
and v.target_type = #{targetType}
and u.nickname like concat('%', #{nickname}, '%')
and v.view_time >= #{beginCreateTime}
and v.view_time < date_add(#{endCreateTime}, interval 1 day)
order by v.view_time desc, v.id desc
